	@Test
	void savesUnicodeAndPreviouslyAcceptedPrefixForms() throws Exception {
		List<String> prefixes = List.of("a\u0300", "a.middle", "\uD800\uDC00name", "_xml", "1legacy", "-legacy",
				"legacy.");

		for (int i = 0; i < prefixes.size(); i++) {
			String prefix = prefixes.get(i);
			String namespace = "http://example.org/ns/" + i + "/";
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(saveRequest(prefix, namespace, null), response);

			assertThat(response.getStatus()).as("prefix %s", prefix).isEqualTo(302);
			assertThat(namespaces()).as("prefix %s", prefix).contains(prefix + "=" + namespace);
		}
	}

	@Test
	void explicitRenameAndDeleteKeepImportedPrefixIdentity() throws Exception {
		setNamespace("_xml", "http://example.org/xml/");
		importTurtle("@prefix a\u0300: <http://example.org/unicode/> .\n");
		setNamespace("b\u0301", "http://example.org/unicode-delete/");
		setNamespace("trailing.", "http://example.org/trailing-dot/");

		MockHttpServletResponse renameResponse = new MockHttpServletResponse();
		servlet.service(saveRequest("renamed", "http://example.org/renamed/", "a\u0300"), renameResponse);
		assertThat(renameResponse.getStatus()).isEqualTo(302);
		assertThat(namespaces()).contains("renamed=http://example.org/renamed/")
				.noneMatch(ns -> ns.startsWith("a\u0300="));

		MockHttpServletResponse underscoreRenameResponse = new MockHttpServletResponse();
		servlet.service(saveRequest("renamed-xml", "http://example.org/renamed-xml/", "_xml"),
				underscoreRenameResponse);
		assertThat(underscoreRenameResponse.getStatus()).isEqualTo(302);
		assertThat(namespaces()).contains("renamed-xml=http://example.org/renamed-xml/")
				.noneMatch(ns -> ns.startsWith("_xml="));

		MockHttpServletRequest unicodeDeleteRequest = request("POST");
		unicodeDeleteRequest.addParameter("action", "delete");
		unicodeDeleteRequest.addParameter("prefix", "b\u0301");
		MockHttpServletResponse unicodeDeleteResponse = new MockHttpServletResponse();
		servlet.service(unicodeDeleteRequest, unicodeDeleteResponse);
		assertThat(unicodeDeleteResponse.getStatus()).isEqualTo(302);
		assertThat(namespaces()).noneMatch(ns -> ns.startsWith("b\u0301="));

		MockHttpServletRequest deleteRequest = request("POST");
		deleteRequest.addParameter("action", "delete");
		deleteRequest.addParameter("prefix", "trailing.");
		MockHttpServletResponse deleteResponse = new MockHttpServletResponse();
		servlet.service(deleteRequest, deleteResponse);

		assertThat(deleteResponse.getStatus()).isEqualTo(302);
		assertThat(namespaces()).noneMatch(ns -> ns.startsWith("trailing.="));

	}

