	private List<String> namespaces() {
		try (RepositoryConnection connection = repository.getConnection()) {
			return Iterations.asList(connection.getNamespaces())
					.stream()
					.map(ns -> ns.getPrefix() + "=" + ns.getName())
					.toList();
		}
	}

	private void setNamespace(String prefix, String namespace) {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.setNamespace(prefix, namespace);
		}
	}

	private void importTurtle(String turtle) throws Exception {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(new StringReader(turtle), "http://example.org/", RDFFormat.TURTLE);
		}
	}

	private static MockHttpServletRequest saveRequest(String prefix, String namespace, String previousPrefix) {
		MockHttpServletRequest request = request("POST");
		request.addParameter("action", "save");
		request.addParameter("prefix", prefix);
		request.addParameter("namespace", namespace);
		if (previousPrefix != null) {
			request.addParameter("previousPrefix", previousPrefix);
		}
		return request;
	}

	private static MockHttpServletRequest request(String method) {
		MockHttpServletRequest request = new MockHttpServletRequest(method, "/namespaces");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		return request;
	}

	private static List<JsonNode> records(MockHttpServletResponse response) throws Exception {
		return response.getContentAsString().lines().map(NamespacesServletPageDataTest::readTree).toList();
	}

	private static JsonNode readTree(String line) {
		try {
			return JSON_MAPPER.readTree(line);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}

	private static String errorMessage(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.map(record -> record.path("values").path("error-message").asText())
				.filter(message -> !message.isEmpty())
				.findFirst()
				.orElse("");
	}

	private static String metadata(List<JsonNode> records, String name) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.map(record -> record.path("values").path(name).asText())
				.filter(value -> !value.isEmpty())
				.findFirst()
				.orElse("");
	}

	private static List<String> column(List<JsonNode> records, int index) {
		List<String> values = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(row -> values.add(row.get(index).path("value").asText()));
			}
		}
		return values;
	}
